    "name": "standup",
    "title": "Standup",
    "description": "Posts yesterday's finished to-dos every morning.",
    "journal": "2.60.0",
    "requires": {"node": {"check": "node --version", "hint": "install Node 20"}},
    "setup": [{"name": "packages", "run": "npm install"}],
